{"op":"define","syntaxVersion":2,"source":"record BatchBounds {
    minimum: Int
    maximum: Int
    validate batch::bounds-valid;
}

fn batch.bounds-valid(value: BatchBounds) -> Bool {
    effects none
    doc "Return whether the minimum is positive and the maximum is at least the minimum."
    if int.greater-or-equal(value.minimum, 1) {
        int.greater-or-equal(value.maximum, value.minimum)
    } else {
        false
    }
}

fn batch.span(value: BatchBounds) -> Int {
    effects none
    doc "Return the difference between the maximum and minimum bounds."
    ::subtract(value.maximum, value.minimum)
}

test batch.span/positive { batch::span(batch::BatchBounds(minimum: 1, maximum: 5)) => 4 }
test batch.span/equal-endpoints { batch::span(batch::BatchBounds(minimum: 3, maximum: 3)) => 0 }
test batch.span/rejects-zero-minimum { batch::span(batch::BatchBounds(minimum: 0, maximum: 3)) => error RECORD_VALIDATION_FAILED }
test batch.span/rejects-reversed-endpoints { batch::span(batch::BatchBounds(minimum: 3, maximum: 2)) => error RECORD_VALIDATION_FAILED }"}

